#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""RQ2 denylist table (denylist V2) — generated by reading only rq2_final.jsonl.

Table A (main) : Public denylist ∩ globals actually used by benign models. Row = denylisted item, items with benign>=1.
                 Each file is attributed to a single item -> row sum = file total.
Table B        : Malicious-only denylisted items (zero benign use). Items separated by the list alone.
File_Attribution : Full list of attributed files.

FP/TP definitions
  FP (Review) = benign with H1(Review)=1,  FP (Unsafe) = benign with n_unsafe>=1
  TP (Review) = malicious with H1=1,        TP (Unsafe) = malicious with n_unsafe>=1
Usage: python3 rq2_table.py --final rq2_final.jsonl --out RQ2_denylist.xlsx
"""
import argparse, json, collections
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter

AR = 'Arial'
ORIGIN_KO = {
    'hf_top': 'Public repository (FP-inducing)', 'hf_hard_benign': 'Public repository (hard benign)',
    'pickleball': 'Prior-study corpus', 'malhug': 'Prior-study corpus',
    'picklecloak': 'Public gadget catalog', 'crafted': 'Crafted',
}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--final', required=True)
    ap.add_argument('--out', required=True)
    ap.add_argument('--top-n', type=int, default=8)
    a = ap.parse_args()
    recs = [json.loads(l) for l in open(a.final, encoding='utf-8') if l.strip()]
    # denylist-involved files: use tags (full) if present, otherwise the resolved entry.
    dl = [r for r in recs if (r.get('denylist_tags') or r.get('denylist_entry'))]

    def tagset(r):
        t = r.get('denylist_tags') or ([r['denylist_entry']] if r.get('denylist_entry') else [])
        return set(t)

    # item frequency (all benign+malicious) -> attribute each file to its single rarest item (same as original pipeline)
    freq = collections.Counter()
    for r in dl:
        freq.update(tagset(r))

    ab = collections.defaultdict(set)
    am = collections.defaultdict(set)
    RB = {}
    for r in dl:
        RB[r['sample_id']] = r
        ts = tagset(r)
        entry = min(ts, key=lambda c: (freq[c], c))     # re-attribution: rarest item
        (ab if r['side'] == 'benign' else am)[entry].add(r['sample_id'])

    def stat(B, M):
        w = lambda S: sum(1 for s in S if RB[s]['H1'])
        u = lambda S: sum(1 for s in S if RB[s]['n_unsafe'] >= 1)
        return dict(nb=len(B), nm=len(M), fpw=w(B), fpu=u(B), tpw=w(M), tpu=u(M),
                    ben_org=collections.Counter(RB[s]['origin'] for s in B),
                    files_b=sorted(B), files_m=sorted(M))
    rows = {c: stat(ab.get(c, set()), am.get(c, set())) for c in set(ab) | set(am)}
    shared = sorted([c for c in rows if rows[c]['nb']], key=lambda c: -rows[c]['nb'])
    malonly = sorted([c for c in rows if not rows[c]['nb']], key=lambda c: (-rows[c]['nm'], c))

    wb = Workbook()
    HDR = PatternFill('solid', fgColor='DCE6F1'); SUB = PatternFill('solid', fgColor='F2F2F2')
    bd = Border(*[Side('thin', color='BFBFBF')] * 4)

    def head(ws, cols, r0=1):
        for j, c in enumerate(cols, 1):
            x = ws.cell(r0, j, c); x.font = Font(AR, bold=True); x.fill = HDR; x.border = bd
            x.alignment = Alignment('center', 'center', wrap_text=True)

    def put(ws, r, vals, bold=False, fill=None):
        for j, v in enumerate(vals, 1):
            x = ws.cell(r, j, v); x.font = Font(AR, bold=bold); x.border = bd
            if fill:
                x.fill = fill
            if j > 1:
                x.alignment = Alignment('center')

    def widths(ws, w):
        for i, v in enumerate(w, 1):
            ws.column_dimensions[get_column_letter(i)].width = v

    # Table A
    ws = wb.active; ws.title = 'TableA_Main'
    ws['A1'] = 'Table A — Denylisted globals that benign models actually use'
    ws['A1'].font = Font(AR, bold=True, size=12)
    ws['A2'] = ('Row = denylisted item. Wildcard entries are grouped by module. '
                'Each file is attributed to a single item -> row sum = file total.')
    ws['A2'].font = Font(AR, italic=True, size=9)
    head(ws, ['Denylisted item', 'Benign files', 'Malicious files', 'FP (Review)', 'FP (Unsafe)', 'TP (Review)', 'TP (Unsafe)', 'Origin of benign files'], 4)
    r = 5; T = collections.Counter()
    for c in shared:
        d = rows[c]
        org = ' · '.join(f'{ORIGIN_KO.get(k, k)} {v}' for k, v in d['ben_org'].most_common())
        put(ws, r, [c, d['nb'], d['nm'], f"{d['fpw']}/{d['nb']}", f"{d['fpu']}/{d['nb']}",
                    f"{d['tpw']}/{d['nm']}" if d['nm'] else '—',
                    f"{d['tpu']}/{d['nm']}" if d['nm'] else '—', org])
        for k in ('nb', 'nm', 'fpw', 'fpu', 'tpw', 'tpu'):
            T[k] += d[k]
        r += 1
    put(ws, r, ['Subtotal', T['nb'], T['nm'], f"{T['fpw']}/{T['nb']}", f"{T['fpu']}/{T['nb']}",
                f"{T['tpw']}/{T['nm']}", f"{T['tpu']}/{T['nm']}", ''], True, SUB)
    ws.cell(r + 2, 1, 'Rows with 0 malicious measure false positives only: being denylisted with no malicious instance is itself a pure false-positive source.'
            ).font = Font(AR, italic=True, size=9)
    widths(ws, [34, 10, 10, 12, 12, 12, 12, 46])

    # Table B (full)
    ws3 = wb.create_sheet('TableB_Full')
    ws3['A1'] = 'Table B — Malicious-only denylisted globals (zero benign use)'
    ws3['A1'].font = Font(AR, bold=True, size=12)
    head(ws3, ['Denylisted item', 'Malicious files', 'TP (Review)', 'TP (Unsafe)', 'Files (sample)'], 3)
    r = 4; M = collections.Counter()
    for c in malonly:
        d = rows[c]
        put(ws3, r, [c, d['nm'], f"{d['tpw']}/{d['nm']}", f"{d['tpu']}/{d['nm']}",
                     ', '.join(d['files_m'][:12])])
        for k in ('nm', 'tpw', 'tpu'):
            M[k] += d[k]
        r += 1
    put(ws3, r, ['Subtotal', M['nm'], f"{M['tpw']}/{M['nm']}", f"{M['tpu']}/{M['nm']}", ''], True, SUB)
    widths(ws3, [44, 12, 12, 12, 70])

    # File_Attribution
    ws5 = wb.create_sheet('File_Attribution')
    head(ws5, ['Denylisted item', 'Side', 'sample_id', 'tier', 'Origin', 'RoPS Review', 'RoPS Unsafe'], 1)
    r = 2
    for c in shared + malonly:
        d = rows[c]
        for s in d['files_b']:
            put(ws5, r, [c, 'Benign', s, RB[s]['tier'], ORIGIN_KO.get(RB[s]['origin'], RB[s]['origin']),
                         'O' if RB[s]['H1'] else '', 'O' if RB[s]['n_unsafe'] >= 1 else '']); r += 1
        for s in d['files_m']:
            put(ws5, r, [c, 'Malicious', s, RB[s]['tier'], ORIGIN_KO.get(RB[s]['origin'], RB[s]['origin']),
                         'O' if RB[s]['H1'] else '', 'O' if RB[s]['n_unsafe'] >= 1 else '']); r += 1
    widths(ws5, [44, 8, 14, 8, 26, 12, 12])

    wb.save(a.out)
    tb = sum(rows[c]['nb'] for c in rows); tm = sum(rows[c]['nm'] for c in rows)
    print(f'-> {a.out}')
    print(f'TableA shared {len(shared)} rows · TableB malonly {len(malonly)} rows | file totals benign {tb} · malicious {tm}')
    print('TableA:', [(c, rows[c]['nb'], rows[c]['nm']) for c in shared])


if __name__ == '__main__':
    main()
